def repeatedRows(matrix):
    row_to_index = {}
    result = []
    for i, row in enumerate(matrix):
        # Convert row to a tuple to use as a key in the dictionary
        row_tuple = tuple(row)
        if row_tuple in row_to_index:
            result.append(i)
        else:
            row_to_index[row_tuple] = i
    return result
